parameters.jsCode:
const items = $input.all();

function estaVacio(valor) {
  if (valor === null || valor === undefined) return true;

  const texto = String(valor).trim().toUpperCase();

  return [
    "",
    "NO ENCONTRADO",
    "NO ENCONTRADA",
    "NO IDENTIFICADO",
    "NO IDENTIFICADA",
    "NO_IDENTIFICADO",
    "NO_IDENTIFICADA",
    "SIN_CONTACTO",
    "N/A",
    "NULL"
  ].includes(texto);
}

function normalizarDescriptivo(valor) {
  return estaVacio(valor) ? "NO IDENTIFICADO" : String(valor).trim();
}

function normalizarContacto(valor) {
  return estaVacio(valor) ? "NO ENCONTRADO" : String(valor).trim();
}

return items.map((item) => {

  // ============================================================
  // 1. LEER LA RESPUESTA JSON DE OLLAMA
  // ============================================================

  let datos;

  try {
    const contenido = item.json.message?.content;

    if (!contenido) {
      throw new Error("Ollama no devolvió message.content");
    }

    datos = typeof contenido === "string"
      ? JSON.parse(contenido)
      : contenido;

  } catch (error) {
    throw new Error(
      "RHIA CORE no pudo interpretar la respuesta de Ollama: " +
      error.message
    );
  }


  // ============================================================
  // 2. DATOS BÁSICOS
  // ============================================================

  const empresa = normalizarDescriptivo(datos.empresa);
  const tipoNegocio = normalizarDescriptivo(datos.tipo_negocio);
  const sector = normalizarDescriptivo(datos.sector);
  const subsector = normalizarDescriptivo(datos.subsector);
  const pais = normalizarDescriptivo(datos.pais);
  const ciudad = normalizarDescriptivo(datos.ciudad);

  const numeroColaboradores =
    Number.isFinite(Number(datos.numero_colaboradores))
      ? Number(datos.numero_colaboradores)
      : 0;

  const necesidades = Array.isArray(datos.necesidades_detectadas)
    ? datos.necesidades_detectadas
        .filter(Boolean)
        .map(x => String(x).trim())
    : [];

  const soluciones = Array.isArray(datos.soluciones_potenciales)
    ? datos.soluciones_potenciales
        .filter(Boolean)
        .map(x => String(x).trim())
    : [];


  // ============================================================
  // 3. RANGO DE EMPRESA — REGLA DETERMINÍSTICA
  // ============================================================

  let rangoEmpresa = "NO IDENTIFICADO";

  if (numeroColaboradores >= 500) {
    rangoEmpresa = "500+";
  } else if (numeroColaboradores >= 200) {
    rangoEmpresa = "200-499";
  } else if (numeroColaboradores >= 50) {
    rangoEmpresa = "50-199";
  } else if (numeroColaboradores >= 10) {
    rangoEmpresa = "10-49";
  }


  // ============================================================
  // 4. VALIDACIÓN DEL PROSPECTO
  // ============================================================

  let estadoValidacion;
  let prospectoValido;

  if (numeroColaboradores >= 10) {
    estadoValidacion = "VALIDO";
    prospectoValido = true;

  } else if (numeroColaboradores > 0) {
    estadoValidacion = "NO_VALIDO";
    prospectoValido = false;

  } else {
    estadoValidacion = "PENDIENTE";
    prospectoValido = false;
  }


  // ============================================================
  // 5. PRIORIDAD COMERCIAL
  //
  // 10+ colaboradores + necesidad concreta = ALTA
  // 10+ colaboradores sin necesidad clara = MEDIA
  // ============================================================

  let prioridadComercial;

  if (numeroColaboradores >= 10 && necesidades.length > 0) {
    prioridadComercial = "ALTA";
  } else if (numeroColaboradores >= 10) {
    prioridadComercial = "MEDIA";
  } else {
    prioridadComercial = "BAJA";
  }


  // ============================================================
  // 6. DATOS DE CONTACTO
  //
  // PRIORIDAD OPERATIVA #1:
  // Persona + cargo + email + WhatsApp/teléfono
  // ============================================================

  const persona = normalizarContacto(datos.persona_contacto);
  const cargo = normalizarContacto(datos.cargo_contacto);
  const email = normalizarContacto(datos.email);
  const whatsapp = normalizarContacto(datos.whatsapp);
  const telefono = normalizarContacto(datos.telefono);

  const tienePersona = persona !== "NO ENCONTRADO";
  const tieneCargo = cargo !== "NO ENCONTRADO";
  const tieneEmail = email !== "NO ENCONTRADO";
  const tieneWhatsapp = whatsapp !== "NO ENCONTRADO";
  const tieneTelefono = telefono !== "NO ENCONTRADO";

  const tieneTelefonoOWhatsapp =
    tieneWhatsapp || tieneTelefono;


  // ============================================================
  // 7. CONTACTABILIDAD
  // ============================================================

  let contactabilidad;

  if (
    tienePersona &&
    tieneEmail &&
    tieneTelefonoOWhatsapp
  ) {
    contactabilidad = "ALTA";

  } else if (
    (tienePersona || tieneCargo) &&
    (tieneEmail || tieneTelefonoOWhatsapp)
  ) {
    contactabilidad = "MEDIA";

  } else if (
    tieneEmail || tieneTelefonoOWhatsapp
  ) {
    contactabilidad = "BAJA";

  } else {
    contactabilidad = "SIN_CONTACTO";
  }


  // ============================================================
  // 8. QUÉ CONTACTOS FALTAN
  // ============================================================

  const datosContactoFaltantes = [];

  if (!tienePersona) {
    datosContactoFaltantes.push("PERSONA_CONTACTO");
  }

  if (!tieneCargo) {
    datosContactoFaltantes.push("CARGO_CONTACTO");
  }

  if (!tieneEmail) {
    datosContactoFaltantes.push("EMAIL");
  }

  if (!tieneTelefonoOWhatsapp) {
    datosContactoFaltantes.push("WHATSAPP_O_TELEFONO");
  }

  const busquedaContactoRequerida =
    datosContactoFaltantes.length > 0;


  // ============================================================
  // 9. NIVEL DEL CONTACTO
  //
  // La capacidad de decisión es SOLO un factor.
  // Nunca invalida un contacto.
  // ============================================================

  let nivelContacto = normalizarDescriptivo(
    datos.nivel_contacto
  );

  let capacidadDecision = normalizarDescriptivo(
    datos.capacidad_decision_estimada
  );

  if (!tienePersona) {
    nivelContacto = "NO IDENTIFICADO";
    capacidadDecision = "NO IDENTIFICADA";
  }


  // ============================================================
  // 10. NIVEL DE INTENCIÓN
  //
  // No asumir que está cotizando o buscando proveedor.
  // ============================================================

  let nivelIntencion = "NO_IDENTIFICADO";

  const intencionOriginal =
    String(datos.nivel_intencion || "")
      .trim()
      .toUpperCase();

  const intencionesFuertesPermitidas = [
    "BUSCANDO_PROVEEDOR",
    "COTIZANDO",
    "COMPRA_PROXIMA"
  ];

  if (
    intencionesFuertesPermitidas.includes(intencionOriginal)
  ) {
    nivelIntencion = intencionOriginal;

  } else if (necesidades.length > 0) {
    nivelIntencion = "NECESIDAD_IDENTIFICADA";
  }


  // ============================================================
  // 11. MOTIVO DE PRIORIDAD
  // ============================================================

  let motivoPrioridad;

  if (
    numeroColaboradores >= 10 &&
    necesidades.length > 0
  ) {
    motivoPrioridad =
      `Cumple el mínimo de ${numeroColaboradores} colaboradores ` +
      `y presenta una necesidad comercial concreta: ` +
      `${necesidades.join(", ")}.`;

  } else if (numeroColaboradores >= 10) {
    motivoPrioridad =
      "Cumple el mínimo de 10 colaboradores, pero todavía debe identificarse una necesidad comercial concreta.";

  } else if (numeroColaboradores > 0) {
    motivoPrioridad =
      "No cumple actualmente el mínimo de 10 colaboradores.";

  } else {
    motivoPrioridad =
      "Falta determinar el número de colaboradores antes de validar el prospecto.";
  }


  // ============================================================
  // 12. ACCIÓN RECOMENDADA
  //
  // PRIMERO CONTACTABILIDAD.
  // ============================================================

  let accionRecomendada;

  if (
    prospectoValido &&
    busquedaContactoRequerida
  ) {
    accionRecomendada =
      "INVESTIGAR_CONTACTO_PRIORITARIAMENTE";

  } else if (
    prospectoValido &&
    !busquedaContactoRequerida
  ) {
    accionRecomendada =
      "INICIAR_CONTACTO_COMERCIAL";

  } else if (
    estadoValidacion === "PENDIENTE"
  ) {
    accionRecomendada =
      "COMPLETAR_INVESTIGACION";

  } else {
    accionRecomendada =
      "NO_PRIORIZAR";
  }


  // ============================================================
  // 13. DATOS GENERALES FALTANTES
  // ============================================================

  const datosFaltantes = [];

  if (empresa === "NO IDENTIFICADO") {
    datosFaltantes.push("EMPRESA");
  }

  if (tipoNegocio === "NO IDENTIFICADO") {
    datosFaltantes.push("TIPO_NEGOCIO");
  }

  if (sector === "NO IDENTIFICADO") {
    datosFaltantes.push("SECTOR");
  }

  if (subsector === "NO IDENTIFICADO") {
    datosFaltantes.push("SUBSECTOR");
  }

  if (pais === "NO IDENTIFICADO") {
    datosFaltantes.push("PAIS");
  }

  if (ciudad === "NO IDENTIFICADO") {
    datosFaltantes.push("CIUDAD");
  }


  // ============================================================
  // 14. FUENTES
  // ============================================================

  const fuentes = Array.isArray(datos.fuentes)
    ? datos.fuentes.filter(Boolean)
    : [];


  // ============================================================
  // 15. RESUMEN COMERCIAL CONSISTENTE
  // ============================================================

  const nombreResumen =
    empresa === "NO IDENTIFICADO"
      ? "La organización"
      : empresa;

  let resumenComercial = "";

  if (numeroColaboradores > 0) {
    resumenComercial +=
      `${nombreResumen} tiene ${numeroColaboradores} colaboradores ` +
      `y pertenece al rango ${rangoEmpresa}. `;
  } else {
    resumenComercial +=
      `${nombreResumen} no tiene aún un tamaño identificado. `;
  }

  if (necesidades.length > 0) {
    resumenComercial +=
      `Necesidades detectadas: ${necesidades.join(", ")}. `;
  } else {
    resumenComercial +=
      "Todavía no se ha identificado una necesidad comercial concreta. ";
  }

  resumenComercial +=
    `Prioridad comercial: ${prioridadComercial}. ` +
    `Contactabilidad: ${contactabilidad}. `;

  if (busquedaContactoRequerida) {
    resumenComercial +=
      `La prioridad operativa es localizar ${datosContactoFaltantes.join(", ")}.`;
  } else {
    resumenComercial +=
      "Los datos básicos para iniciar contacto comercial están disponibles.";
  }


  // ============================================================
  // 16. RESULTADO FINAL RHIA CORE
  // ============================================================

  return {
    json: {

      empresa,

      estado_validacion: estadoValidacion,
      prospecto_valido: prospectoValido,
      prioridad_comercial: prioridadComercial,

      tipo_negocio: tipoNegocio,
      sector,
      subsector,

      numero_colaboradores: numeroColaboradores,
      rango_empresa: rangoEmpresa,

      pais,
      ciudad,

      necesidades_detectadas: necesidades,
      soluciones_potenciales: soluciones,

      nivel_intencion: nivelIntencion,

      persona_contacto: persona,
      cargo_contacto: cargo,
      email,
      whatsapp,
      telefono,

      nivel_contacto: nivelContacto,
      capacidad_decision_estimada: capacidadDecision,

      contactabilidad,

      busqueda_contacto_requerida: busquedaContactoRequerida,
      datos_contacto_faltantes: datosContactoFaltantes,

      fuentes,

      motivo_prioridad: motivoPrioridad,
      accion_recomendada: accionRecomendada,

      datos_faltantes: datosFaltantes,

      resumen_comercial: resumenComercial
    }
  };
});

const busqueda = $input.first().json;
const contexto = $("Edit Fields1").first().json;

const empresa = String(
  contexto.empresa || "NO IDENTIFICADO"
).trim();

if (
  !empresa ||
  empresa === "NO IDENTIFICADO" ||
  empresa === "NO ENCONTRADO"
) {
  throw new Error(
    "RHIA INVESTIGADOR: no existe una empresa identificada para investigar."
  );
}

const resultados = Array.isArray(busqueda.results)
  ? busqueda.results
  : [];


// ============================================================
// FUNCIONES GENERALES
// ============================================================

function limpiarTexto(valor) {
  return String(valor || "")
    .replace(/\s+/g, " ")
    .trim();
}

function textoComparable(valor) {
  return limpiarTexto(valor)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}


// ============================================================
// RECUPERAR URL DESDE SEARXNG
// ============================================================

function obtenerUrl(resultado) {

  if (
    typeof resultado.url === "string" &&
    resultado.url.trim()
  ) {
    return resultado.url.trim();
  }

  const parsed = resultado.parsed_url;

  if (
    Array.isArray(parsed) &&
    parsed.length >= 3 &&
    parsed[0] &&
    parsed[1]
  ) {

    const protocolo = String(parsed[0]);
    const dominio = String(parsed[1]);
    const ruta = String(parsed[2] || "");
    const query = String(parsed[4] || "");
    const fragmento = String(parsed[5] || "");

    let url =
      `${protocolo}://${dominio}${ruta}`;

    if (query) {
      url += `?${query}`;
    }

    if (fragmento) {
      url += `#${fragmento}`;
    }

    return url;
  }

  return "";
}


// ============================================================
// EXTRAER DOMINIO
// ============================================================

function obtenerDominio(url) {

  const coincidencia =
    String(url || "").match(
      /^https?:\/\/([^\/?#]+)/i
    );

  if (!coincidencia) {
    return "";
  }

  return coincidencia[1]
    .replace(/^www\./i, "")
    .toLowerCase();
}


// ============================================================
// TOKENS REALES DEL NOMBRE EMPRESARIAL
// ============================================================

function palabrasMarca(nombre) {

  const legales = new Set([
    "sa",
    "sas",
    "s",
    "a",
    "cia",
    "ltda",
    "limitada",
    "inc",
    "llc",
    "plc"
  ]);

  return textoComparable(nombre)
    .split(/[^a-z0-9]+/)
    .filter(
      palabra =>
        palabra.length >= 2 &&
        !legales.has(palabra)
    );
}


// ============================================================
// IDENTIDAD DE LA EMPRESA
// ============================================================

const empresaComparable =
  textoComparable(empresa);

const tokensEmpresa =
  palabrasMarca(empresa);

const empresaCompacta =
  tokensEmpresa.join("");


// ============================================================
// PALABRAS IMPORTANTES
// ============================================================

const palabrasContacto = [
  "contacto",
  "contact",
  "telefono",
  "teléfono",
  "phone",
  "celular",
  "movil",
  "móvil",
  "whatsapp",
  "correo",
  "email",
  "e-mail",
  "dirección",
  "direccion",
  "directorio"
];

const palabrasPersonas = [
  "linkedin",
  "talento humano",
  "recursos humanos",
  "rrhh",
  "human resources",
  "gerente",
  "director",
  "jefe",
  "coordinador",
  "analista",
  "asistente",
  "administracion",
  "administración",
  "recepcion",
  "recepción"
];

const dominiosSociales = [
  "linkedin.com",
  "facebook.com",
  "instagram.com",
  "x.com",
  "twitter.com"
];

const dominiosDirectorios = [
  "google.com",
  "maps.google",
  "paginasamarillas",
  "yellowpages",
  "zoominfo",
  "apollo",
  "crunchbase"
];


// ============================================================
// ANALIZAR RESULTADOS
// ============================================================

const procesados = [];

for (const resultado of resultados) {

  const titulo =
    limpiarTexto(resultado.title);

  const contenido =
    limpiarTexto(resultado.content);

  const url =
    obtenerUrl(resultado);

  const dominio =
    obtenerDominio(url);

  const engine =
    limpiarTexto(resultado.engine);

  if (!url || !dominio) {
    continue;
  }

  const combinado =
    textoComparable(
      `${titulo} ${contenido} ${url}`
    );

  const dominioComparable =
    textoComparable(dominio)
      .replace(/[^a-z0-9]/g, "");

  let puntuacion = 0;
  const razones = [];

  let dominioEmpresaExacto = false;
  let dominioEmpresaFuerte = false;


  // ==========================================================
  // 1. NOMBRE COMPLETO DE EMPRESA EN RESULTADO
  // ==========================================================

  if (
    empresaComparable &&
    combinado.includes(empresaComparable)
  ) {
    puntuacion += 50;
    razones.push("NOMBRE_EMPRESA");
  }


  // ==========================================================
  // 2. COINCIDENCIA DE PALABRAS DEL NOMBRE
  // ==========================================================

  const tokensCoincidentes =
    tokensEmpresa.filter(
      token =>
        combinado.includes(token)
    );

  if (tokensEmpresa.length > 0) {

    const proporcion =
      tokensCoincidentes.length /
      tokensEmpresa.length;

    if (proporcion === 1) {

      puntuacion += 40;

      razones.push(
        "COINCIDENCIA_COMPLETA_EMPRESA"
      );

    } else if (proporcion >= 0.75) {

      puntuacion += 30;

      razones.push(
        "ALTA_COINCIDENCIA_EMPRESA"
      );

    } else if (proporcion >= 0.5) {

      puntuacion += 15;

      razones.push(
        "COINCIDENCIA_PARCIAL_EMPRESA"
      );
    }
  }


  // ==========================================================
  // 3. DOMINIO CON NOMBRE COMPLETO DE LA EMPRESA
  //
  // Corporación Favorita
  // → corporacionfavorita
  // → corporacionfavorita.com
  //
  // PRIORIDAD MUY ALTA
  // ==========================================================

  if (
    empresaCompacta.length >= 5 &&
    dominioComparable.includes(
      empresaCompacta
    )
  ) {

    puntuacion += 180;

    dominioEmpresaExacto = true;

    razones.push(
      "DOMINIO_EMPRESA_EXACTO"
    );
  }


  // ==========================================================
  // 4. TODOS LOS TOKENS DE LA EMPRESA DENTRO DEL DOMINIO
  // ==========================================================

  const tokensEnDominio =
    tokensEmpresa.filter(
      token =>
        dominioComparable.includes(token)
    );

  if (
    !dominioEmpresaExacto &&
    tokensEmpresa.length >= 2 &&
    tokensEnDominio.length ===
      tokensEmpresa.length
  ) {

    puntuacion += 110;

    dominioEmpresaFuerte = true;

    razones.push(
      "DOMINIO_EMPRESA_FUERTE"
    );
  }


  // ==========================================================
  // 5. SOLO UNA PALABRA DE LA EMPRESA EN EL DOMINIO
  //
  // Ejemplo:
  // Favorita → favoritabananas.com
  //
  // NO debe considerarse automáticamente web oficial.
  // ==========================================================

  if (
    !dominioEmpresaExacto &&
    !dominioEmpresaFuerte &&
    tokensEnDominio.length === 1 &&
    tokensEmpresa.length >= 2
  ) {

    puntuacion += 5;

    razones.push(
      "DOMINIO_COINCIDENCIA_DEBIL"
    );
  }


  // ==========================================================
  // 6. CONTACTO
  // ==========================================================

  const coincidenciasContacto =
    palabrasContacto.filter(
      palabra =>
        combinado.includes(
          textoComparable(palabra)
        )
    );

  if (
    coincidenciasContacto.length > 0
  ) {

    puntuacion += Math.min(
      40,
      coincidenciasContacto.length * 10
    );

    razones.push(
      "POSIBLE_DATO_CONTACTO"
    );
  }


  // ==========================================================
  // 7. PÁGINA ESPECÍFICA DE CONTACTO
  // ==========================================================

  if (
    combinado.includes("contacto") ||
    combinado.includes("contact us") ||
    /\/contact(o)?\/?$/i.test(url)
  ) {

    puntuacion += 35;

    razones.push(
      "PAGINA_CONTACTO"
    );
  }


  // ==========================================================
  // 8. PERSONA / CARGO
  // ==========================================================

  const coincidenciasPersonas =
    palabrasPersonas.filter(
      palabra =>
        combinado.includes(
          textoComparable(palabra)
        )
    );

  if (
    coincidenciasPersonas.length > 0
  ) {

    puntuacion += Math.min(
      30,
      coincidenciasPersonas.length * 6
    );

    razones.push(
      "POSIBLE_PERSONA_CARGO"
    );
  }


  // ==========================================================
  // 9. TIPO DE FUENTE
  // ==========================================================

  let tipoFuente = "WEB";

  if (
    dominiosSociales.some(
      d => dominio.includes(d)
    )
  ) {

    tipoFuente =
      "RED_PROFESIONAL_SOCIAL";

    puntuacion += 5;
  }


  if (
    dominiosDirectorios.some(
      d => dominio.includes(d)
    )
  ) {

    tipoFuente =
      "DIRECTORIO";

    puntuacion += 8;
  }


  if (
    dominioEmpresaExacto ||
    dominioEmpresaFuerte
  ) {

    tipoFuente =
      "POSIBLE_WEB_OFICIAL";
  }


  // ==========================================================
  // 10. PENALIZAR POSIBLES FALSOS POSITIVOS
  // ==========================================================

  if (
    tokensEmpresa.length >= 2 &&
    tokensEnDominio.length === 1 &&
    !combinado.includes(
      empresaComparable
    )
  ) {

    puntuacion -= 30;

    razones.push(
      "POSIBLE_EMPRESA_HOMONIMA"
    );
  }


  // ==========================================================
  // 11. NOTICIAS
  // ==========================================================

  if (
    /\/20\d{2}\//.test(url) ||
    combinado.includes("noticia") ||
    combinado.includes("news")
  ) {

    puntuacion -= 15;

    razones.push(
      "ARTICULO_NOTICIA"
    );
  }


  // ==========================================================
  // GUARDAR RESULTADO
  // ==========================================================

  procesados.push({

    titulo,
    url,
    dominio,
    contenido,
    engine,

    tipo_fuente: tipoFuente,

    puntuacion,

    razones,

    identidad_empresa: {
      dominio_empresa_exacto:
        dominioEmpresaExacto,

      dominio_empresa_fuerte:
        dominioEmpresaFuerte,

      tokens_empresa:
        tokensEmpresa,

      tokens_en_dominio:
        tokensEnDominio
    }
  });
}


