function obtenerFragmentos(texto) {

  const palabras = [
    "correo",
    "email",
    "teléfono",
    "telefono",
    "whatsapp",
    "contacto",
    "trabaja con nosotros",
    "talento",
    "recursos humanos",
    "selección",
    "seleccion",
    "colaboradores",
    "empleados",
    "quiénes somos",
    "quienes somos",
    "ecuador",
    "quito",
    "guayaquil"
  ];

  const textoLower =
    texto.toLowerCase();

  const fragmentos = [];

  for (const palabra of palabras) {

    let posicion =
      textoLower.indexOf(palabra);

    while (posicion >= 0) {

      const inicio =
        Math.max(0, posicion - 250);

      const fin =
        Math.min(
          texto.length,
          posicion + palabra.length + 450
        );

      fragmentos.push(
        limpiarEspacios(
          texto.slice(inicio, fin)
        )
      );

      posicion =
        textoLower.indexOf(
          palabra,
          posicion + palabra.length
        );
    }
  }

  return unicos(fragmentos)
    .slice(0, 15);
}


