// ============================================================
// FUNCIONES GENERALES
// ============================================================

function limpiar(texto) {
  return String(texto || "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizar(texto) {
  return limpiar(texto)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function dominioDe(url) {
  return String(url || "")
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "")
    .split("/")[0]
    .split("?")[0]
    .split("#")[0]
    .split(":")[0];
}

function contiene(texto, valor) {
  return normalizar(texto)
    .includes(normalizar(valor));
}


// ============================================================
// PERSONA
// ============================================================

function mencionaPersona(texto, personaCompleta) {

  const t = normalizar(texto);
  const persona = normalizar(personaCompleta);

  if (!persona) return false;

  if (t.includes(persona)) {
    return true;
  }

  const partes = persona
    .split(/\s+/)
    .filter(Boolean);

  if (partes.length >= 2) {

    const nombreCorto =
      `${partes[0]} ${partes[1]}`;

    if (
      nombreCorto.length >= 6 &&
      t.includes(nombreCorto)
    ) {
      return true;
    }
  }

  return false;
}


function urlContienePersona(url, personaCompleta) {

  let u = "";

  try {
    u = decodeURIComponent(
      String(url || "")
    );
  } catch {
    u = String(url || "");
  }

  u = normalizar(u)
    .replace(/[^a-z0-9]+/g, " ");

  const partes =
    normalizar(personaCompleta)
      .split(/\s+/)
      .filter(Boolean);

  if (partes.length < 2) {
    return false;
  }

  return (
    u.includes(partes[0]) &&
    u.includes(partes[1])
  );
}


function fuentePrincipalPersona(
  titulo,
  url,
  persona
) {

  return (
    mencionaPersona(
      titulo,
      persona
    ) ||
    urlContienePersona(
      url,
      persona
    )
  );
}


// ============================================================
// EMAILS
// ============================================================

function extraerEmails(texto) {

  const matches =
    String(texto || "").match(
      /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi
    ) || [];

  return [
    ...new Set(
      matches.map(e =>
        e.toLowerCase()
      )
    )
  ];
}


function tieneEmailEnmascarado(texto) {

  return (
    /[A-Za-z0-9]*[*xX]{2,}@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/i
      .test(String(texto || ""))
  );
}


// ============================================================
// TELÉFONOS
// ============================================================

function normalizarTelefono(valor) {

  const original =
    String(valor || "").trim();

  const prefijo =
    original.startsWith("+")
      ? "+"
      : "";

  const digitos =
    original.replace(/\D/g, "");

  if (
    digitos.length < 7 ||
    digitos.length > 15
  ) {
    return "";
  }

  return prefijo + digitos;
}


function tieneTelefonoEnmascarado(texto) {

  return (
    /(?:\+?\d[\d\s().-]*)(?:X{2,}|x{2,}|\*{2,}|\.{3,})/i
      .test(String(texto || ""))
  );
}


// ============================================================
// ELIMINAR RANGOS DE FECHAS
//
// Evita convertir:
// 1989 - 1990
// 2017 - 2018
// 1990 - now
// en teléfonos.
// ============================================================

function eliminarRangosFechas(texto) {

  return String(texto || "")
    .replace(
      /\b(?:19|20)\d{2}\s*(?:-|–|—|a|to)\s*(?:(?:19|20)\d{2}|now|present|presente|actualidad|hoy)\b/gi,
      " "
    );
}


function pareceDosAnios(numero) {

  const digitos =
    String(numero || "")
      .replace(/\D/g, "");

  if (digitos.length !== 8) {
    return false;
  }

  const a =
    Number(digitos.slice(0, 4));

  const b =
    Number(digitos.slice(4, 8));

  return (
    a >= 1900 &&
    a <= 2099 &&
    b >= 1900 &&
    b <= 2099
  );
}


// ============================================================
// EXTRAER TELÉFONOS REALES
//
// Aceptamos:
//
// +593...
// 09...
// 02...
// números que estén inmediatamente asociados
// a palabras como teléfono / phone / celular.
//
// No aceptamos secuencias arbitrarias de números.
// ============================================================

function extraerTelefonosCompletos(texto) {

  const t =
    eliminarRangosFechas(
      String(texto || "")
    );

  const candidatos = [];


  // Internacionales con +
  const internacionales =
    t.match(
      /\+\s*\d[\d\s().-]{6,}\d/g
    ) || [];

  candidatos.push(
    ...internacionales
  );


  // Números locales que empiezan por 0
  const locales =
    t.match(
      /\b0\d[\d\s().-]{6,}\d\b/g
    ) || [];

  candidatos.push(
    ...locales
  );


  // Número expresamente etiquetado como teléfono
  const regexContexto =
    /(?:tel[eé]fono|tel\.?|phone|celular|m[oó]vil|mobile|whatsapp)\s*(?:[:\-]|al|es)?\s*(\+?\d[\d\s().-]{6,}\d)/gi;

  let match;

  while (
    (match =
      regexContexto.exec(t)) !== null
  ) {

    candidatos.push(
      match[1]
    );
  }


  const salida = [];

  for (const candidato of candidatos) {

    const numero =
      normalizarTelefono(
        candidato
      );

    if (!numero) {
      continue;
    }

    if (
      pareceDosAnios(numero)
    ) {
      continue;
    }

    salida.push(numero);
  }

  return [
    ...new Set(salida)
  ];
}


// ============================================================
// 1800 ECUADOR
// ============================================================

function extraer1800(texto) {

  const t =
    String(texto || "");

  const resultados = [];

  const regex =
    /1800(?:\s+[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+)?\s*\(?\s*(\d{3})\s*(\d{3})\s*\)?/gi;

  let match;

  while (
    (match =
      regex.exec(t)) !== null
  ) {

    resultados.push(
      `1800${match[1]}${match[2]}`
    );
  }

  return [
    ...new Set(resultados)
  ];
}


// ============================================================
// WHATSAPP
//
// Solo se acepta cuando la fuente dice expresamente WhatsApp.
// ============================================================

function extraerWhatsAppExplicito(texto) {

  const t =
    String(texto || "");

  if (
    !/\bwhatsapp\b/i.test(t)
  ) {
    return [];
  }

  if (
    tieneTelefonoEnmascarado(t)
  ) {
    return [];
  }

  return extraerTelefonosCompletos(t);
}


// ============================================================
// FUENTE OFICIAL
// ============================================================

function esWebOficialCorporacionFavorita(url) {

  return dominioDe(url) ===
    "corporacionfavorita.com";
}


// ============================================================
// DEDUPLICAR
// ============================================================

function deduplicarContactos(lista) {

  const vistos =
    new Set();

  return lista.filter(c => {

    const clave =
      `${c.tipo}|${normalizar(c.valor)}|${c.fuente}`;

    if (
      vistos.has(clave)
    ) {
      return false;
    }

    vistos.add(clave);

    return true;
  });
}


// ============================================================
// PROCESAMIENTO
// ============================================================

const salida = [];

for (
  let i = 0;
  i < respuestas.length;
  i++
) {

  const respuesta =
    respuestas[i]?.json || {};

  const candidato =
    candidatos[i]?.json || {};

  const persona =
    candidato.persona_contacto ||
    "NO ENCONTRADO";

  const empresa =
    candidato.empresa ||
    "NO IDENTIFICADO";

  const cargo =
    candidato.cargo_contacto ||
    "NO IDENTIFICADO";

  const resultados =
    Array.isArray(respuesta.results)
      ? respuesta.results
      : [];


  const contactosDirectos = [];
  const contactosEmpresaOficiales = [];
  const contactosEmpresaSecundarios = [];
  const contactosEnmascarados = [];
  const resultadosDescartados = [];
  const fuentesRevisadas = [];


  for (const r of resultados) {

    const titulo =
      limpiar(r.title);

    const contenido =
      limpiar(r.content);

    const url =
      limpiar(r.url);

    const dominio =
      dominioDe(url);

    const texto =
      `${titulo} ${contenido}`;


    const personaMencionada =
      mencionaPersona(
        texto,
        persona
      );


    // MUY IMPORTANTE:
    // Para atribuir un contacto a Gitta,
    // la página debe ser principalmente sobre Gitta.
    const personaPrincipal =
      fuentePrincipalPersona(
        titulo,
        url,
        persona
      );


    const empresaPresente =
      (
        contiene(
          texto,
          "Corporacion Favorita"
        ) ||
        contiene(
          texto,
          "Corporación Favorita"
        )
      );


    // ========================================================
    // HOMÓNIMOS
    // ========================================================

    if (
      dominio ===
      "favoritabananas.com"
    ) {

      resultadosDescartados.push({

        titulo,

        url,

        motivo:
          "EMPRESA_HOMONIMA_NO_CORPORACION_FAVORITA"
      });

      continue;
    }


    const emailEnmascarado =
      tieneEmailEnmascarado(texto);

    const telefonoEnmascarado =
      tieneTelefonoEnmascarado(texto);


    // ========================================================
    // CONTACTO ENMASCARADO DE LA PERSONA OBJETIVO
    // ========================================================

    if (
      personaPrincipal &&
      empresaPresente &&
      (
        emailEnmascarado ||
        telefonoEnmascarado
      )
    ) {

      contactosEnmascarados.push({

        tipo:
          "CONTACTO_PERSONA_ENMASCARADO",

        valor:
          "NO UTILIZABLE",

        persona_contacto:
          persona,

        fuente:
          url,

        dominio,

        evidencia:
          texto,

        utilizable:
          false,

        motivo:
          "CONTACTO_ENMASCARADO"
      });
    }


    // ========================================================
    // CONTACTO DIRECTO DE LA PERSONA
    // ========================================================

    if (
      personaPrincipal &&
      empresaPresente
    ) {

      // EMAIL
      if (
        !emailEnmascarado
      ) {

        const emails =
          extraerEmails(texto);

        for (const email of emails) {

          contactosDirectos.push({

            tipo:
              "EMAIL",

            valor:
              email,

            persona_contacto:
              persona,

            fuente:
              url,

            dominio,

            evidencia:
              texto,

            estado:
              "PUBLICO_NO_ENMASCARADO"
          });
        }
      }


      // TELÉFONO
      if (
        !telefonoEnmascarado
      ) {

        const telefonos =
          extraerTelefonosCompletos(
            texto
          );

        for (
          const telefono of telefonos
        ) {

          contactosDirectos.push({

            tipo:
              "TELEFONO",

            valor:
              telefono,

            persona_contacto:
              persona,

            fuente:
              url,

            dominio,

            evidencia:
              texto,

            estado:
              "PUBLICO_NO_ENMASCARADO"
          });
        }


        const whatsapp =
          extraerWhatsAppExplicito(
            texto
          );

        for (
          const numero of whatsapp
        ) {

          contactosDirectos.push({

            tipo:
              "WHATSAPP",

            valor:
              numero,

            persona_contacto:
              persona,

            fuente:
              url,

            dominio,

            evidencia:
              texto,

            estado:
              "WHATSAPP_DECLARADO_EXPLICITAMENTE"
          });
        }
      }
    }


    // ========================================================
    // CONTACTO GENERAL OFICIAL
    // ========================================================

    if (
      esWebOficialCorporacionFavorita(
        url
      )
    ) {

      const emails =
        extraerEmails(texto);

      const telefonos =
        [
          ...extraerTelefonosCompletos(
            texto
          ),
          ...extraer1800(texto)
        ];

      const whatsapp =
        extraerWhatsAppExplicito(
          texto
        );


      for (const email of emails) {

        contactosEmpresaOficiales.push({

          tipo:
            "EMAIL_EMPRESA",

          valor:
            email,

          fuente:
            url,

          evidencia:
            texto,

          estado:
            "VERIFICADO_WEB_OFICIAL"
        });
      }


      for (
        const telefono of telefonos
      ) {

        contactosEmpresaOficiales.push({

          tipo:
            "TELEFONO_EMPRESA",

          valor:
            telefono,

          fuente:
            url,

          evidencia:
            texto,

          estado:
            "VERIFICADO_WEB_OFICIAL"
        });
      }


      for (
        const numero of whatsapp
      ) {

        contactosEmpresaOficiales.push({

          tipo:
            "WHATSAPP_EMPRESA",

          valor:
            numero,

          fuente:
            url,

          evidencia:
            texto,

          estado:
            "WHATSAPP_DECLARADO_WEB_OFICIAL"
        });
      }
    }


    // ========================================================
    // CONTACTO CORPORATIVO EN FUENTES SECUNDARIAS
    // ========================================================

    if (
      !personaPrincipal &&
      empresaPresente &&
      !esWebOficialCorporacionFavorita(
        url
      )
    ) {

      const emails =
        emailEnmascarado
          ? []
          : extraerEmails(texto);

      const telefonos =
        telefonoEnmascarado
          ? []
          : extraerTelefonosCompletos(
              texto
            );


      for (const email of emails) {

        contactosEmpresaSecundarios.push({

          tipo:
            "EMAIL_EMPRESA_NO_OFICIAL",

          valor:
            email,

          fuente:
            url,

          evidencia:
            texto,

          estado:
            "FUENTE_SECUNDARIA"
        });
      }


      for (
        const telefono of telefonos
      ) {

        contactosEmpresaSecundarios.push({

          tipo:
            "TELEFONO_EMPRESA_NO_OFICIAL",

          valor:
            telefono,

          fuente:
            url,

          evidencia:
            texto,

          estado:
            "FUENTE_SECUNDARIA"
        });
      }
    }


    fuentesRevisadas.push({

      titulo,

      url,

      dominio,

      persona_mencionada:
        personaMencionada,

      persona_principal:
        personaPrincipal,

      empresa_presente:
        empresaPresente
    });
  }


  // ==========================================================
  // DEDUPLICAR
  // ==========================================================

  const directos =
    deduplicarContactos(
      contactosDirectos
    );

  const oficiales =
    deduplicarContactos(
      contactosEmpresaOficiales
    );

  const secundarios =
    deduplicarContactos(
      contactosEmpresaSecundarios
    );

  const enmascarados =
    deduplicarContactos(
      contactosEnmascarados
    );


  // ==========================================================
  // ESTADO FINAL
  // ==========================================================

  const estadoContacto =
    directos.length > 0
      ? "CONTACTO_DIRECTO_PUBLICO_ENCONTRADO"
      : "SIN_CONTACTO_DIRECTO_VERIFICADO";


  salida.push({

    json: {

      empresa,

      persona_contacto:
        persona,

      cargo_contacto:
        cargo,

      estado_contacto:
        estadoContacto,

      contactos_directos:
        directos,

      contactos_empresa_oficiales:
        oficiales,

      contactos_empresa_secundarios:
        secundarios,

      contactos_enmascarados_no_utilizables:
        enmascarados,

      total_contactos_directos:
        directos.length,

      total_contactos_empresa_oficiales:
        oficiales.length,

      whatsapp_directo_verificado:
        directos.some(
          c =>
            c.tipo === "WHATSAPP"
        ),

      siguiente_accion:
        directos.length > 0
          ? "VALIDAR_CONTACTO_Y_PREPARAR_PROSPECCION"
          : oficiales.length > 0
            ? "AMPLIAR_BUSQUEDA_CONTACTO_DIRECTO_MANTENIENDO_CONTACTO_EMPRESA"
            : "AMPLIAR_BUSQUEDA_CONTACTO_DIRECTO",

      fuentes_revisadas:
        fuentesRevisadas,

      resultados_descartados:
        resultadosDescartados
    }
  });
}


return salida;
